import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringWriter;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class WordWrapTest {

    @Test
    public void fromReader ReturnsBuilder() {
        // given
        Reader reader = Mockito.mock(Reader.class);
        when(reader.ready()).thenReturn(true);

        // when
        WordWrap.Builder builder = WordWrap.from(reader);

        // then
        assertNotNull(builder);
    }

    @Test
    public void fromClasspathUtf8 ReturnsBuilder() {
        // given
        String resource = "test.resource";

        // when
        WordWrap.Builder builder = WordWrap.fromClasspathUtf8(resource);

        // then
        assertNotNull(builder);
    }

    @Test
    public void fromFileUtf8 ReturnsBuilder() {
        // given
        File file = new File("test.file");
        Charset charset = StandardCharsets.UTF_8;

        // when
        WordWrap.Builder builder = WordWrap.from(file, charset);

        // then
        assertNotNull(builder);
    }

    @Test
    public void wordWrapReaderWriter ReturnsNumber() throws IOException {
        // given
        Reader in = new BufferedReader(new InputStreamReader(System.in));
        Writer out = new StringWriter();
        String newLine = "\n";
        Number maxWidth = 10L;
        Function<? super CharSequence, ? extends Number> stringWidth = Mockito.mock(Function.class);
        Set<Character> extraWordChars = new HashSet<>();
        boolean insertHyphens = false;
        boolean breakWords = true;

        // when
        WordWrap.wordWrap(in, out, newLine, maxWidth, stringWidth, extraWordChars, insertHyphens, breakWords);

        // then
        Number result = when(stringWidth.apply("hello world")).thenReturn(10L);
        wordWrapReaderWriter(in, out, newLine, maxWidth, stringWidth, extraWordChars, insertHyphens, breakWords, result);
    }

    @Test
    public void wordWrapReaderConsumer ReturnsNumber() throws IOException {
        // given
        Reader in = new BufferedReader(new InputStreamReader(System.in));
        LineConsumer out = Mockito.mock(LineConsumer.class);
        Number maxWidth = 10L;
        Function<? super CharSequence, ? extends Number> stringWidth = Mockito.mock(Function.class);
        Set<Character> extraWordChars = new HashSet<>();
        boolean insertHyphens = false;
        boolean breakWords = true;

        // when
        WordWrap.wordWrap(in, out, maxWidth, stringWidth, extraWordChars, insertHyphens, breakWords);

        // then
        Number result = when(stringWidth.apply("hello world")).thenReturn(10L);
        wordWrapReaderConsumer(in, out, maxWidth, stringWidth, extraWordChars, insertHyphens, breakWords, result);
    }

    @Test
    public void rightTrim ReturnsString() {
        // given
        CharSequence s = "   hello world  ";

        // when
        String result = WordWrap.rightTrim(s);

        // then
        assertEquals("hello world", result);
    }

    @Test
    public void isWhitespace ReturnsBoolean() {
        // given
        CharSequence s = "hello";

        // when
        boolean result = WordWrap.isWhitespace(s);

        // then
        assertFalse(result);
    }

    @Test
    public void leftTrimBuilder2 ReturnsString() {
        // given
        StringBuilder2 word = Mockito.mock(StringBuilder2.class);
        String originalText = "   hello world  ";

        // when
        String result = WordWrap.leftTrim(word).toString();

        // then
        assertEquals(originalText, result);
    }

    @Test
    public void fromUtf8InputStream ReturnsBuilder() {
        // given
        InputStream in = Mockito.mock(InputStream.class);

        // when
        WordWrap.Builder builder = WordWrap.fromUtf8(in);

        // then
        assertNotNull(builder);
    }
}
